/**
 * @fileoverview A package that did not create the instance (#714). It is loaded before slothlet and no module imports
 * it, so slothlet has no loader recorded for it, and it builds the same closures the owner's `context.mjs` does.
 * @module stranger-pkg
 */

/**
 * Build the context.
 * @param {object} api - The bound api a `slothlet()` call returned.
 * @returns {Record<string, Function>} The context.
 */
export function makeContext(api) {
	return {
		pin: (fn) => typeof api.slothlet.lockCaller(fn),
		meta: () => api.slothlet.metadata.caller()?.apiPath ?? null,
		emit: () => {
			api.slothlet.event.emit("host:ping", { n: 1 });
			return "emitted";
		},
		hostLeaf: () => api.host.echo("x")
	};
}
